def replace_paragraph(paragraph, value):
    runs = paragraph.runs
    if runs:
        runs[0].text = value
        for run in runs[1:]:
            run.text = ""
    else:
        paragraph.add_run().text = value

for slide_no, shape_map in replacements.items():
    slide = prs.slides[slide_no - 1]
    for shape_idx, values in shape_map.items():
        shape = slide.shapes[shape_idx]
        if not shape.has_text_frame:
            raise ValueError(f"Slide {slide_no}, shape {shape_idx} is not text")
        paragraphs = shape.text_frame.paragraphs
        if len(paragraphs) != len(values):
            raise ValueError(f"Slide {slide_no}, shape {shape_idx}: expected {len(paragraphs)} paragraphs, got {len(values)}")
        for paragraph, value in zip(paragraphs, values):
            replace_paragraph(paragraph, value)

prs.save(out)
print(f"Saved {out} with {len(prs.slides)} slides")
